"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1417],{79756:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"DevCommandsService","desc":"Server side of the dev-only chat commands registered in NovaChat\'s\\n`Commands.client.luau`. Chat commands execute on the client, so anything\\ntouching authoritative state has to come back through a packet \u2014 this is the\\nhandler for those.\\n\\nEvery command here is gated on `isAuthorised`, which mirrors the check\\nNovaChat\'s own `ChatHandler.server.luau` uses for moderation actions: the\\nplace owner, or rank 250+ in the owning group. Unauthorised callers are\\nignored (with a `warn`, so an attempt is visible in the server log) rather\\nthan answered, since a reply would only tell an exploiter where the gate is.\\n\\nCommands are deliberately **self-only**: none of them takes a target player.\\nThat keeps the worst case of a missed gate to \\"a player can inconvenience\\nthemselves\\".","realm":["Server"],"source":{"line":22,"path":"src/ServerScriptService/DevCommandsService.server.luau"}}')}}]);